    const zipCode = context?.Form?.Page1?.SiteAddressZipcode?.Value || "";

    // Define a map for common directional prefixes and street suffixes to their standardized forms
    const directionMap = {
        'N': 'N',
        'S': 'S',
        'E': 'E',
        'W': 'W',
        'NE': 'NE',
        'NW': 'NW',
        'SE': 'SE',
        'SW': 'SW',
        'NORTH': 'N',
        'SOUTH': 'S',
        'EAST': 'E',
        'WEST': 'W',
        'NORTHEAST': 'NE',
        'NORTHWEST': 'NW',
        'SOUTHEAST': 'SE',
        'SOUTHWEST': 'SW'
    };

    const suffixMap = {
        'ST': 'ST',
        'STREET': 'ST',
        'RD': 'RD',
        'ROAD': 'RD',
        'AVE': 'AVE',
        'AVENUE': 'AVE',
        'BLVD': 'BLVD',
        'BOULEVARD': 'BLVD',
        'DR': 'DR',
        'DRIVE': 'DR',
        'CT': 'CT',
        'COURT': 'CT',
        'CIR': 'CIR',
        'CIRCLE': 'CIR',
        'LN': 'LN',
        'LANE': 'LN'
    };

    // Standardize and clean the street address
    let cleanStreet = street
