        return name.replace(/[^\w\s]|_/g, '').replace(/\s+/g, ' ').trim().toUpperCase();
    };

    // Clean and uppercase the names
    firstName = cleanAndUppercase(firstName);
    lastName = cleanAndUppercase(lastName);
    middleName = cleanAndUppercase(middleName);

    // Conditionally include middle name only if it's not empty
    const formattedName = middleName
        ? `${firstName} ${middleName} ${lastName}`
        : `${firstName} ${lastName}`;

    return formattedName.trim(); // Trim any extra spaces
};
