        return dateTime ? dateTime.split(" ")[0] : "";
    };

    // Extract values with fallback to an empty string
    const assignedDate = extractDate(context?.Form?.Page1?.LeadAssignedDate?.Value || "");
    const leadDate = extractDate(context?.Form?.Page1?.LeadCompletedDate?.Value || "");
    const enrollmentDate = extractDate(context?.Form?.Page1?.EnrollmentDate?.Value || "");
    const assessmentDate = extractDate(context?.Form?.Page1?.AssessmentDate?.Value || "");
    const installationDate = extractDate(context?.Form?.Page1?.InstallationCompletedDate?.Value || "");
    const completedDate = extractDate(context?.Form?.Page1?.JobCompletedDate?.Value || "");
    const canceledDate = extractDate(context?.Form?.Page1?.CanceledDate?.Value || "");
    const projectStage = context?.Form?.Page1?.ProjectStage?.Value || "";
    const projectStatus = context?.Form?.Page1?.ComputedProjectStatus?.Value || "";
    const projectReason = context?.Form?.Page1?.ProjectReason?.Value || "";

    // Handle canceled projects first
    if (projectReason !== "") {
        return canceledDate;
    }

    // Return the corresponding date based on project stage and status
    if (projectStage == "Lead") {
        return assignedDate;
    } else if (projectStage == "Enrollment") {
        return leadDate;
    } else if (projectStatus == "Invoiced") {
        return invoicedDate;
    } else if (projectStage == "Assessment") {
        return enrollmentDate;
    } else if (projectStage == "Installation" && projectStatus == "Installed") {
        return installationDate;
    } else if (projectStage == "Installation") {
        return assessmentDate;
    } else if (projectStage == "Completed") {
        return completedDate;
    }

    // Default return if no conditions are met
