const SetValue = async (context) => {
    const totalIncome = parseFloat(context?.Form?.PrimaryMemberMonthlyIncome?.Value) || 0;
    const incomeFrequency = context?.Form?.PrimaryIncomeMonths?.Value || "";

    // Determine the frequency multiplier
    let frequencyMultiplier;

    if (incomeFrequency == "Weekly") {
        frequencyMultiplier = 52;
    } else if (incomeFrequency == "Bi-weekly") {
        frequencyMultiplier = 26;
    } else if (incomeFrequency == "Monthly") {
        frequencyMultiplier = 12;
    } else if (incomeFrequency == "Bi-Monthly") {
        frequencyMultiplier = 24;
    } else if (incomeFrequency == "Seasonal") {
        frequencyMultiplier = 1/12;
    } else {
        frequencyMultiplier = 1;
    }

    // Calculate and return
    return Number((totalIncome * frequencyMultiplier).toFixed(2));
};","ClearValueOnTrue":false,"ClearValueOnFalse":false,"Key":null,"Fields":[{"ModelKey":"Form.PrimaryMemberMonthlyIncome","FieldName":"PrimaryMemberMonthlyIncome","IsSystemModelKey":false},{"ModelKey":"Form.PrimaryIncomeMonths","FieldName":"PrimaryIncomeMonths","IsSystemModelKey":false}]}

